<div class="coa"><h1>Chart of Account</h1><div class="coa-grid"><section class="coa-tree"><ul>@php $draw=null;$draw=function($items,$depth=0)use(&$draw){foreach($items as $account){echo '<li><button type="button" class="coa-node'.($depth===0?' active':'').'" data-id="'.$account->id.'" data-code="'.e($account->code).'" data-name="'.e($account->head_name).'" data-parent="'.e($account->parent?->head_name??'Root account').'" data-group="'.($account->is_group?'1':'0').'"><i class="bi '.($account->is_group?'bi-folder-fill':'bi-file-earmark-text').' "></i><span>'.e($account->head_name).'</span><small>'.e($account->code).'</small></button>';if($account->children->isNotEmpty()){echo '<ul>';$draw($account->children,$depth+1);echo '</ul>';}echo '</li>';}};$draw($nodes);@endphp</ul></section><section class="coa-detail"><h2 id="coa-name">Select an account</h2><p>Choose a group from the account tree to create a sub-account.</p><div class="coa-info"><label>Head code<span id="coa-code">—</span></label><label>Parent head<span id="coa-parent-name">—</span></label></div><form method="POST" action="{{ route('admin.accounts.coa.store') }}" class="coa-form">@csrf<h5>Create sub-account</h5><label>Parent group<select name="parent_id" id="coa-parent" required><option value="">Choose group account</option>@foreach($groups as $group)<option value="{{ $group->id }}">{{ $group->code }} — {{ $group->head_name }}</option>@endforeach</select></label><label>Account head name<input name="head_name" placeholder="e.g. Petty Cash" required></label><button>Create account head</button></form></section></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const parent=document.querySelector('#coa-parent');document.querySelectorAll('.coa-node').forEach(node=>{const children=node.parentElement.querySelector(':scope > ul');if(children){node.insertAdjacentHTML('afterbegin','<i class="bi bi-caret-down-fill coa-toggle"></i>');}node.addEventListener('click',event=>{if(event.target.closest('.coa-toggle')){children.hidden=!children.hidden;event.target.closest('.coa-toggle').className=`bi bi-caret-${children.hidden?'right':'down'}-fill coa-toggle`;return;}document.querySelectorAll('.coa-node').forEach(item=>item.classList.remove('active'));node.classList.add('active');document.querySelector('#coa-name').textContent=node.dataset.name;document.querySelector('#coa-code').textContent=node.dataset.code;document.querySelector('#coa-parent-name').textContent=node.dataset.parent;if(node.dataset.group==='1')parent.value=node.dataset.id;});});});</script>
